  str_files_story_des_101 = "Todos menos Nikinis preencheram o Formulário de Informações Básicas. Por que ela não quer preenchê-lo?",
  str_files_story_des_103 = "Inesperadamente, encontrei duas Nikinis! Será que uma delas é a irmã mais velha de quem tanto fala?! Não consigo distinguir uma da outra...",
  str_files_story_des_105 = "História 5",
  str_files_story_des_107 = "História 7",
  str_files_story_des_110 = "História 10",
  str_files_story_des_201 = "Você pressente que alguém está te vigiando por toda parte ultimamente e, para atrair quem está te seguindo, anda de forma desajeitada...",
  str_files_story_des_203 = "Seu superior é surpreendentemente calmo, mas a aura poderosa ainda é algo que te perturba. Você tem uma dúvida que gostaria de saber se deve perguntar...",
  str_files_story_des_205 = "História 5",
  str_files_story_des_207 = "História 7",
  str_files_story_des_209 = "História 9",
  str_files_story_des_210 = "História 10",
  str_files_story_des_402 = "História 2",
