  str_files_story_des_1004 = "História 4",
  str_files_story_des_1006 = "História 6",
  str_files_story_des_1008 = "História 8",
  str_files_story_des_1009 = "História 9",
  str_files_story_des_1102 = "Hoje não é dia de inspeção, mas você sente uma grande pressão porque Sharona, uma Comandante Illumina, comentará sobre as operações na Colossus! Tomara que tudo corra bem...",
  str_files_story_des_1104 = "Sharona parece ter suas razões para ficar de olho na Colossus e em você. Talvez tenha percebido algo em você que atende algumas das expectativas dela...",
  str_files_story_des_1106 = "História 5",
  str_files_story_des_1108 = "História 7",
  str_files_story_des_1110 = "História 10",
  str_files_story_des_1201 = "Assuntos triviais são motivo de discussões intensas na Colossus! Mesmo a contragosto, você terá que apaziguar a situação...",
  str_files_story_des_1203 = "Parece que a Srta. Nemesis é obcecada por imparcialidade e justiça. Seria bom se você conversasse mais com ela para conhecer melhor seu lado oculto...",
  str_files_story_des_1205 = "História 5",
  str_files_story_des_1207 = "História 7",
  str_files_story_des_1210 = "História 10",
  str_files_story_des_1302 = "História 2",
  str_files_story_des_1304 = "História 4",
  str_files_story_des_1306 = "História 6",
  str_files_story_des_1308 = "História 8",
  str_files_story_des_1309 = "História 9",
  str_files_story_des_1310 = "História 10",
  str_files_story_des_1402 = "O Senhor da Cidade veio inspecionar a Colossus?! Com os nervos à flor da pele, você acaba se atrasando. É melhor se esforçar para não dar mais mancadas!",
  str_files_story_des_1404 = "Por que o amável Senhor da Cidade se aproximou de você de forma tão agressiva? O que está acontecendo?! Como responsável pela Colossus, você sente novamente aquele olhar de expectativa e decepção...",
  str_files_story_des_1406 = "História 6",
  str_files_story_des_1408 = "História 8",
  str_files_story_des_1409 = "História 9",
  str_files_story_des_1410 = "História 10",
  str_files_story_des_1701 = "História 1",
  str_files_story_des_1703 = "História 3",
  str_files_story_des_1705 = "História 5",
  str_files_story_des_1707 = "História 7",
  str_files_story_des_1802 = "Um convite para um show de música ao vivo? Enquanto decide se deve ir a esse evento estranho em vez de descansar, alguém bate com violência na porta...",
  str_files_story_des_1804 = "É hoje. Você questiona como será o show de música ao vivo de Regina e começa a sentir uma certa inquietação...",
  str_files_story_des_1806 = "História 6",
