  str_files_story_des_2101 = "História 1",
  str_files_story_des_2103 = "História 3",
  str_files_story_des_2105 = "História 5",
  str_files_story_des_2107 = "História 7",
  str_files_story_des_2201 = "História 1",
  str_files_story_des_2203 = "História 3",
