  str_files_story_des_2307 = "História 9",
  str_files_story_des_2310 = "História 10",
  str_files_story_des_2501 = "Mais um dia recebendo inúmeras reclamações sobre Charon. Hora de ter uma conversinha com ele.",
  str_files_story_des_2503 = "É impossível ter uma conversa normal com Charon. Faça o possível para obter mais informações e talvez consiga descobrir sua obsessão.",
  str_files_story_des_2505 = "História 5",
  str_files_story_des_2507 = "História 7",
  str_files_story_des_2509 = "História 9",
  str_files_story_des_2510 = "História 10",
  str_files_story_des_2602 = "História 2",
