  str_files_story_des_2606 = "História 6",
  str_files_story_des_2608 = "História 8",
  str_files_story_des_2609 = "História 9",
  str_files_story_des_2610 = "História 10",
  str_files_story_des_2801 = "Você continua com a sensação de que algo ruim vai acontecer... O que será? Ah, aquela é a Raphaela? Por que está acenando... feito doida?",
  str_files_story_des_2803 = "A busca de Raphaela por melhores tratamentos de saúde é problemática. Ainda bem que não está cometendo nenhuma travessura hoje, ou até você reclamaria...",
  str_files_story_des_2805 = "História 5",
  str_files_story_des_2807 = "História 7",
  str_files_story_des_2809 = "História 9",
  str_files_story_des_2810 = "História 10",
  str_files_story_des_2902 = "História 2",
  str_files_story_des_2904 = "História 4",
  str_files_story_des_2906 = "História 6",
  str_files_story_des_2908 = "História 8",
  str_files_story_des_2909 = "História 9",
  str_files_story_des_2910 = "História 10",
  str_files_story_des_3202 = "História 2",
  str_files_story_des_3204 = "História 4",
  str_files_story_des_3206 = "História 6",
  str_files_story_des_3301 = "Pergunta: Quão bem você conhece essa velha amiga com quem sai diariamente? Sabe o que ela realmente pensa? Talvez não seja uma resposta fácil de conseguir...",
  str_files_story_des_3303 = "Por que a inspeção da Vice mais parece uma avaliação? A ansiedade é grande, mas você espera que ela pegue leve independentemente do que seja...",
  str_files_story_des_3305 = "História 6",
  str_files_story_des_3307 = "História 8",
  str_files_story_des_3310 = "História 10",
  str_files_story_des_3501 = "Eho tem atrasado bastante as entregas ultimamente. Por quê será? Tente conversar com ela a respeito...",
  str_files_story_des_3503 = "Parece que Eho tem um péssimo senso de direção... Não deve ser fácil para ela realizar seu trabalho... Então fazer cópias de mapas ajuda mesmo a lembrar?",
  str_files_story_des_3505 = "História 5",
  str_files_story_des_3602 = "História 1",
  str_files_story_des_3604 = "História 3",
  str_files_story_des_3606 = "História 5",
  str_files_story_des_3608 = "História 7",
  str_files_story_des_3610 = "História 10",
  str_files_story_des_3802 = "A Srta. Gronru tem se preocupado demais com a manutenção da Colossus ultimamente, além de parecer muito interessada e empolgada com isso. Hoje será sua primeira reunião oficial. Gostaria de saber como é a personalidade dela?",
  str_files_story_des_3804 = "Parece que a Srta. Gronru gosta mesmo de jogos... Espero que isso não afete suas tarefas diárias, senão será difícil de lidar com isso...",
  str_files_story_des_3806 = "História 6",
  str_files_story_des_3808 = "História 8",
  str_files_story_des_3809 = "História 9",
  str_files_story_des_3810 = "História 10",
  str_files_story_des_4001 = "História 1",
  str_files_story_des_4003 = "História 3",
  str_files_story_des_4005 = "História 5",
  str_files_story_des_4007 = "História 7",
  str_files_story_des_4101 = "A Srta. Blanc está sempre ocupada com eventos importantes. Que tal você dar uma conferida? Melhor ainda se puder ajudar em vez de atrapalhar...",
  str_files_story_des_4103 = "Hum... Parece que você piorou mesmo as coisas. Agora a Srta. Blanc está ainda mais atarefada... Será que você consegue compensar de alguma forma?",
  str_files_story_des_4105 = "História 5",
  str_files_story_des_4107 = "História 7",
  str_files_story_des_4402 = "História 2",
  str_files_story_des_4404 = "História 4",
